class Solution {
public:
    vector<int> countPairsOfConnectableServers(vector<vector<int>>& edges, int signalSpeed) {
        int n = edges.size() + 1;
        vector<vector<pair<int, int>>> adj(n);
        for (auto& e : edges) {
            adj[e[0]].push_back({e[1], e[2]});
            adj[e[1]].push_back({e[0], e[2]});
        }
        auto dfs = [&](auto& self, int u, int p, int dist) -> int {
            int count = (dist % signalSpeed == 0) ? 1 : 0;
            for (auto& [v, w] : adj[u]) {
                if (v != p) count += self(self, v, u, dist + w);
            }
            return count;
        };
        vector<int> ans(n, 0);
        for (int i = 0; i < n; ++i) {
            int total_sum = 0, pairs = 0;
            for (auto& [v, w] : adj[i]) {
                int cnt = dfs(dfs, v, i, w);
                pairs += total_sum * cnt;
                total_sum += cnt;
            }
            ans[i] = pairs;
        }
        return ans;
    }
};

class Solution {
    public int[] countPairsOfConnectableServers(int[][] edges, int signalSpeed) {
        int n = edges.length + 1;
        List<int[]>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            adj[e[0]].add(new int[]{e[1], e[2]});
            adj[e[1]].add(new int[]{e[0], e[2]});
        }
        int[] ans = new int[n];
        for (int i = 0; i < n; i++) {
            int totalSum = 0, pairs = 0;
            for (int[] next : adj[i]) {
                int cnt = dfs(next[0], i, next[1], signalSpeed, adj);
                pairs += totalSum * cnt;
                totalSum += cnt;
            }
            ans[i] = pairs;
        }
        return ans;
    }
    private int dfs(int u, int p, int dist, int speed, List<int[]>[] adj) {
        int count = (dist % speed == 0) ? 1 : 0;
        for (int[] next : adj[u]) {
            if (next[0] != p) count += dfs(next[0], u, dist + next[1], speed, adj);
        }
        return count;
    }
}

